CREATE FUNCTION public.owner_launch_input(_task uuid,_input text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t client_tasks; BEGIN SELECT * INTO t FROM client_tasks WHERE id=_task FOR UPDATE; IF t.id IS NULL OR t.client_id IS DISTINCT FROM my_client_id() OR NOT has_role(auth.uid(),'client') OR t.owner_action_kind NOT IN('input','upload') THEN RAISE EXCEPTION 'This task does not request your input'; END IF; IF task_gate_a_locked(t.id) THEN RAISE EXCEPTION 'Locked: waiting for Gate A'; END IF; IF coalesce(trim(_input),'')='' THEN RAISE EXCEPTION 'Enter the requested input'; END IF; INSERT INTO task_activity(task_id,user_id,action,note) VALUES(t.id,auth.uid(),'owner_input',trim(_input)); UPDATE client_tasks SET status='in_progress' WHERE id=t.id; END $$;
REVOKE ALL ON FUNCTION public.owner_launch_input(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.owner_launch_input(uuid,text) TO authenticated;
CREATE FUNCTION public.gate_a_schedule_after() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.gate_code='gate_a' AND NEW.status='signed' AND OLD.status<>'signed' THEN UPDATE client_tasks t SET due_date=launch_due_date((NEW.signed_at AT TIME ZONE 'Asia/Kolkata')::date,t.week_due) WHERE t.launch_id=NEW.launch_id AND t.phase='onboarding' AND coalesce(t.phase_code,(SELECT phase_code FROM launch_modules WHERE code=t.module_code),'P0')<>'P0'; END IF; RETURN NULL; END $$;
REVOKE ALL ON FUNCTION public.gate_a_schedule_after() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER z_gate_a_schedule AFTER UPDATE ON public.client_gates FOR EACH ROW EXECUTE FUNCTION public.gate_a_schedule_after();
DO $ddl$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.gate_approval_guard()'::regprocedure) INTO d; d:=replace(d,'IF NEW.status=''signed'' AND OLD.status<>''signed'' THEN','IF NEW.status=''signed'' AND OLD.status<>''signed'' THEN\n IF NEW.signed_by IS DISTINCT FROM auth.uid() OR NEW.signed_at IS NULL THEN RAISE EXCEPTION ''Gate sign-off must record the signer and time''; END IF;'); d:=replace(d,'THEN\n','THEN'||chr(10)); EXECUTE d; END $ddl$;